func schema_clabernetes_clabernetes_apis_v1alpha1_TopologySpec(
	ref common.ReferenceCallback,
) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "TopologySpec is the spec for a Topology resource.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"definition": {
						SchemaProps: spec.SchemaProps{
							Description: "Definition defines the actual set of nodes (network ones, not k8s ones!) that this Topology CR represents -- a containerlab topology file that will be \"clabernetsified\".",
							Default:     map[string]interface{}{},
							Ref: ref(
								"github.com/clabernetes/clabernetes/apis/v1alpha1.Definition",
							),
						},
					},
					"expose": {
						SchemaProps: spec.SchemaProps{
							Description: "Expose holds configurations relevant to how clabernetes exposes a topology.",
							Default:     map[string]interface{}{},
							Ref: ref(
								"github.com/clabernetes/clabernetes/apis/v1alpha1.Expose",
							),
						},
					},
					"deployment": {
						SchemaProps: spec.SchemaProps{
							Description: "Deployment holds configurations relevant to how clabernetes configures deployments that make up a given topology.",
							Default:     map[string]interface{}{},
							Ref: ref(
								"github.com/clabernetes/clabernetes/apis/v1alpha1.Deployment",
							),
						},
					},
					"statusProbes": {
						SchemaProps: spec.SchemaProps{
							Description: "StatusProbes holds the configurations relevant to how clabernetes and the launcher handle checking and reporting the containerlab node status",
							Default:     map[string]interface{}{},
							Ref: ref(
								"github.com/clabernetes/clabernetes/apis/v1alpha1.StatusProbes",
							),
						},
					},
					"imagePull": {
						SchemaProps: spec.SchemaProps{
							Description: "ImagePull holds configurations relevant to how clabernetes launcher pods handle pulling images.",
							Default:     map[string]interface{}{},
							Ref: ref(
								"github.com/clabernetes/clabernetes/apis/v1alpha1.ImagePull",
							),
						},
					},
					"naming": {
						SchemaProps: spec.SchemaProps{
							Description: "Naming tells the clabernetes controller how it should name resources it creates -- that is whether it should include the containerlab topology name as a prefix on resources spawned from this Topology or not; this includes the actual (containerlab) node Deployment(s), as well as the Service(s) for the Topology. This setting has three modes; \"prefixed\" -- which of course includes the containerlab topology name as a prefix, \"non-prefixed\" which does *not* include the containerlab topology name as a prefix, and \"global\" which defers to the global config setting for this (which defaults to \"prefixed\"). \"non-prefixed\" mode should only be enabled when/if Topologies are deployed in their own namespace -- the reason for this is simple: if two Topologies exist in the same namespace with a (containerlab) node named \"my-router\" there will be a conflicting Deployment and Services for the \"my-router\" (containerlab) node. Note that this field is immutable! If you want to change its value you need to delete the Topology and re-create it.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"connectivity": {
						SchemaProps: spec.SchemaProps{
							Description: "Connectivity defines the type of connectivity to use between nodes in the topology. The default behavior is to use vxlan tunnels, alternatively you can enable a more experimental \"slurpeeth\" connectivity flavor that stuffs traffic into tcp tunnels to avoid any vxlan mtu and/or fragmentation challenges.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
				},
				Required: []string{"definition", "naming"},
			},
		},
		Dependencies: []string{
			"github.com/clabernetes/clabernetes/apis/v1alpha1.Definition", "github.com/clabernetes/clabernetes/apis/v1alpha1.Deployment", "github.com/clabernetes/clabernetes/apis/v1alpha1.Expose", "github.com/clabernetes/clabernetes/apis/v1alpha1.ImagePull", "github.com/clabernetes/clabernetes/apis/v1alpha1.StatusProbes"},
	}
}

func schema_clabernetes_clabernetes_apis_v1alpha1_TopologyStatus(
	ref common.ReferenceCallback,
) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "TopologyStatus is the status for a Topology resource. Note that all *per node* (and per link) state lives on the emitted Node and Link custom resources rather than here -- the Topology only aggregates, which keeps its size bounded regardless of how big the topology definition is.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"kind": {
						SchemaProps: spec.SchemaProps{
							Description: "Kind is the topology kind this CR represents -- \"containerlab\".",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"nodeCount": {
						SchemaProps: spec.SchemaProps{
							Description: "NodeCount is the number of (containerlab) nodes this Topology compiled to.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"readyNodeCount": {
						SchemaProps: spec.SchemaProps{
							Description: "ReadyNodeCount is the number of nodes of this Topology that currently report ready.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"linkCount": {
						SchemaProps: spec.SchemaProps{
							Description: "LinkCount is the number of links this Topology compiled to.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"topologyReady": {
						SchemaProps: spec.SchemaProps{
							Description: "TopologyReady indicates if all nodes in the topology have reported ready. This is duplicated from the conditions so we can easily snag it for print columns!",
							Default:     false,
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"topologyState": {
						SchemaProps: spec.SchemaProps{
							Description: "TopologyState is the high-level lifecycle state of the topology.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"error": {
						SchemaProps: spec.SchemaProps{
							Description: "Error holds a bounded controller error that prevents the Topology from realizing its desired child resources. An empty value means no such error is currently reported.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"conditions": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "Conditions is a list of conditions for the topology custom resource.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Ref: ref("k8s.io/apimachinery/pkg/apis/meta/v1.Condition"),
									},
								},
							},
						},
					},
				},
				Required: []string{"kind", "topologyReady", "conditions"},
			},
		},
		Dependencies: []string{
			"k8s.io/apimachinery/pkg/apis/meta/v1.Condition"},
	}
}

